+/*
+ * HomeNotebookEmbed's own styling — matches index.astro's showcase panel conventions
+ * (font-mono, --accent, --border) since Astro's scoped <style> blocks don't reach into a
+ * Preact island's runtime-rendered DOM.
+ */
+
+.home-notebook-cta {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  margin-top: 16px;
+  padding: 9px 16px;
+  border: 1px solid var(--border-strong);
+  border-radius: var(--radius);
+  background: transparent;
+  color: var(--fg-secondary);
+  font-family: var(--font-mono);
+  font-size: 13px;
+  font-weight: 600;
+  cursor: pointer;
+}
+.home-notebook-cta:hover {
+  border-color: var(--accent);
+  color: var(--accent);
+}
+
+.home-notebook-embed {
+  height: 640px;
+  overflow: hidden;
+  margin-top: 14px;
+  border-top: 1px solid var(--border);
+}
+
+.home-notebook-loading {
+  padding: 20px;
+  font-family: var(--font-mono);
+  font-size: 13px;
+  color: var(--fg-faint);
+}

